// @generated by @frameless/qwik; do not edit.
import { component$, useComputed$, useSignal, useStore } from '@qwik.dev/core';

export const NestedBoard = component$((props) => {
	const groups = useStore(props.seed.map((group) => ({ ...group, rows: group.rows.slice() })));
	const selection = useSignal('none');
	const marked = useSignal('none');
	const cells = useComputed$(() => groups.flatMap((group) => group.rows).length);
	return (
		<section data-scenario="s4">
			<output data-selection="true">{selection.value}</output>
			<p data-count="cells">
				{cells.value}/{groups.length}
			</p>
			<button
				data-action="flip"
				onClick$={async (event) => {
					const flipped = groups.map((group) => ({
						...group,
						rows: group.rows.slice().reverse(),
					}));
					groups.splice(0, groups.length, ...flipped);
					await props.onTrace$(
						'flip',
						{ order: flipped.map((group) => group.id) },
						event,
					);
				}}
			>
				flip
			</button>
			<button
				data-action="reorder"
				onClick$={async (event) => {
					const order = groups.slice().reverse();
					groups.splice(0, groups.length, ...order);
					await props.onTrace$(
						'reorder',
						{ order: order.map((group) => group.id) },
						event,
					);
				}}
			>
				reorder
			</button>
			<ul data-groups="true">
				{groups.map((group) => (
					<li key={group.id} data-oracle-group-key={group.id}>
						<ul data-rows={group.id}>
							{group.rows.map((row) => (
								<li key={row.id} data-oracle-cell-key={row.id}>
									<button
										data-select={row.id}
										onClick$={async (event) => {
											selection.value = `${group.id}>${row.id}`;
											marked.value = row.id;
											await props.onTrace$(
												'select',
												{ group: group.id, row: row.id },
												event,
											);
										}}
									>
										select
									</button>
									{marked.value === row.id ? (
										<span data-cell-on={row.id}>on</span>
									) : (
										<span data-cell-off={row.id}>off</span>
									)}
									<details data-cell-open={row.id}>
										<summary data-open-cell={row.id}>open</summary>
									</details>
								</li>
							))}
						</ul>
					</li>
				))}
			</ul>
		</section>
	);
});
